import unittest

from pathlib import Path


class ReportTests(unittest.TestCase):
    def test_has_alpha(self):
        self.assertIn("alpha", Path("inputs/report.txt").read_text())

    def test_has_beta(self):
        self.assertIn("beta", Path("inputs/report.txt").read_text())

    def test_smoke(self):
        self.assertTrue(Path("inputs/report.txt").exists())

