import sys
import unittest

suite = unittest.defaultTestLoader.loadTestsFromNames(sys.argv[1:])
if unittest.defaultTestLoader.errors:
    raise SystemExit("\n".join(unittest.defaultTestLoader.errors))
for entry in suite:
    for group in entry:
        for test in group if isinstance(group, unittest.TestSuite) else [group]:
            print(test.id())
